// The markup `save()` wrote up to 0.9.2, kept as it was so content saved with
// it still validates. Do not edit this file: its output must not change.
//
// Differences from the current save(): only Default and Preset 1 could sort,
// and the card layouts (Presets 2 to 4) carried no column data.

import { RichText, useBlockProps } from '@wordpress/block-editor';

import {
	PRESET_3,
	columnAlignStyle,
	getCardRoles,
	getCardRowCount,
	getColumnRoles,
	getImageWidth,
	getPlainText,
	headerAlignStyle,
	isBlankCell,
	isCardPreset,
	isNotApplicable,
	isRecipePreset,
	isTablePreset,
} from '../utils';

// The width is set on the image itself, not its wrapper, so a theme rule
// for img cannot bring back the original size. The same value is kept in
// a custom property for the stylesheet, which can hold the width against a
// theme rule that is marked !important.
function renderImage( col, image ) {
	if ( ! image?.url ) {
		return null;
	}

	const width = getImageWidth( col ) + 'px';

	// The wp-image class lets WordPress add srcset, dimensions and lazy
	// loading when rendering.
	const imageClassName =
		image.id > 0
			? `lunar-table__image wp-image-${ image.id }`
			: 'lunar-table__image';

	return (
		<img
			className={ imageClassName }
			src={ image.url }
			alt={ image.alt || '' }
			style={ {
				width,
				height: 'auto',
				'--lunar-table-image-width': width,
			} }
		/>
	);
}

// Text cells may contain inline formatting (bold, italic, link) saved
// by RichText; other cell types are plain values.
function renderCellValue( col, value ) {
	if ( 'image' === col.type ) {
		return renderImage( col, value );
	}

	if ( 'text' === col.type ) {
		return <RichText.Content value={ value ?? '' } />;
	}

	return value ?? '';
}

function renderDividerRow( row, index, cellClassName, colSpan ) {
	return (
		<tr key={ index } className="lunar-table__row--divider">
			<td colSpan={ colSpan } className={ cellClassName }>
				{ row.dividerLabel ?? '' }
			</td>
		</tr>
	);
}

function renderTable( { columns, rows, preset } ) {
	const { imageCol, titleCol } = getColumnRoles( columns );

	function cellClassName( col ) {
		const names = [];

		if ( 'image' === col.type ) {
			names.push( 'lunar-table__cell--image' );
		}

		if ( col === imageCol ) {
			names.push( 'lunar-table__cell--lead' );
		}

		if ( col === titleCol ) {
			names.push( 'lunar-table__cell--title' );
		}

		return names.join( ' ' ) || undefined;
	}

	return (
		<table className="lunar-table__table">
			<thead>
				<tr>
					{ columns.map( ( col ) => (
						<th
							key={ col.key }
							scope="col"
							data-key={ col.key }
							data-type={ col.type }
							style={ headerAlignStyle( col, preset ) }
						>
							{ col.label }
						</th>
					) ) }
				</tr>
			</thead>
			<tbody>
				{ rows.map( ( row, index ) => {
					if ( row.isDivider ) {
						return renderDividerRow(
							row,
							index,
							'lunar-table__divider-cell',
							columns.length
						);
					}

					return (
						<tr key={ index }>
							{ columns.map( ( col ) => (
								<td
									key={ col.key }
									className={ cellClassName( col ) }
									data-label={ col.label }
									data-key={ col.key }
									style={ columnAlignStyle( col, preset ) }
								>
									{ renderCellValue( col, row[ col.key ] ) }
								</td>
							) ) }
						</tr>
					);
				} ) }
			</tbody>
		</table>
	);
}

// A label with its value. Empty and "N/A" values show a muted dash,
// and the row stays so the cards of a grid keep their rows aligned.
function renderCardField( col, value, className ) {
	const isMuted = isBlankCell( col, value ) || isNotApplicable( col, value );

	return (
		<td key={ col.key } className={ className }>
			<span className="lunar-table__card-label">{ col.label }</span>
			<span
				className={
					isMuted
						? 'lunar-table__card-value lunar-table__card-value--muted'
						: 'lunar-table__card-value'
				}
			>
				{ isMuted ? '—' : renderCellValue( col, value ) }
			</span>
		</td>
	);
}

// Roles follow the column type: an image first column, then the title,
// then an optional note, detail rows and an optional highlight band.
function renderCards( { columns, rows, showCardNote, showCardHighlight } ) {
	const { imageCol, titleCol, noteCol, highlightCol, detailCols } =
		getCardRoles( columns, { showCardNote, showCardHighlight } );

	return (
		<table className="lunar-table__cards">
			<tbody>
				{ rows.map( ( row, index ) => {
					if ( row.isDivider ) {
						return renderDividerRow(
							row,
							index,
							'lunar-table__cards-divider-cell'
						);
					}

					const note =
						noteCol &&
						! isBlankCell( noteCol, row[ noteCol.key ] ) &&
						! isNotApplicable( noteCol, row[ noteCol.key ] );

					return (
						<tr key={ index } className="lunar-table__card">
							<td className="lunar-table__card-head">
								{ imageCol &&
									renderImage(
										imageCol,
										row[ imageCol.key ]
									) }
								<span className="lunar-table__card-title">
									{ titleCol
										? renderCellValue(
												titleCol,
												row[ titleCol.key ]
											)
										: '' }
								</span>
								{ note && (
									<span className="lunar-table__card-note">
										{ renderCellValue(
											noteCol,
											row[ noteCol.key ]
										) }
									</span>
								) }
							</td>

							{ detailCols.map( ( col ) =>
								renderCardField(
									col,
									row[ col.key ],
									'lunar-table__card-detail'
								)
							) }

							{ highlightCol &&
								renderCardField(
									highlightCol,
									row[ highlightCol.key ],
									'lunar-table__card-highlight'
								) }
						</tr>
					);
				} ) }
			</tbody>
		</table>
	);
}

// Chips come from the plain text of a cell: a comma splits one cell
// into several chips, which formatted HTML could not do safely.
function splitChips( value ) {
	return getPlainText( value )
		.split( ',' )
		.map( ( part ) => part.trim() )
		.filter( Boolean );
}

function renderRecipeStats( statChips, priceValue ) {
	if ( ! statChips.length && ! priceValue ) {
		return null;
	}

	return (
		<span className="lunar-table__recipe-stats">
			{ statChips.map( ( chip, i ) => (
				<span
					key={ i }
					className="lunar-table__recipe-chip lunar-table__recipe-chip--accent"
				>
					{ chip }
				</span>
			) ) }
			{ priceValue && (
				<span className="lunar-table__recipe-chip">{ priceValue }</span>
			) }
		</span>
	);
}

function renderRecipeField( col, value ) {
	if ( isBlankCell( col, value ) ) {
		return null;
	}

	return (
		<div key={ col.key } className="lunar-table__recipe-field">
			<span className="lunar-table__recipe-field-label">
				{ col.label }
			</span>
			<span className="lunar-table__recipe-field-value">
				{ renderCellValue( col, value ) }
			</span>
		</div>
	);
}

function renderRecipeCard(
	row,
	index,
	{ imageCol, titleCol, statCol, priceCol, fieldCols }
) {
	const statChips = statCol ? splitChips( row[ statCol.key ] ) : [];
	const priceValue = priceCol ? getPlainText( row[ priceCol.key ] ) : '';

	return (
		<tr
			key={ index }
			className="lunar-table__recipe-card"
			data-recipe-id={ row.id }
		>
			<td className="lunar-table__recipe-cell">
				<div className="lunar-table__recipe-header">
					{ imageCol && renderImage( imageCol, row[ imageCol.key ] ) }
					<div className="lunar-table__recipe-info">
						{ titleCol && (
							<span className="lunar-table__recipe-name">
								{ renderCellValue(
									titleCol,
									row[ titleCol.key ]
								) }
							</span>
						) }
						{ renderRecipeStats( statChips, priceValue ) }
					</div>
				</div>

				{ fieldCols.map( ( col ) =>
					renderRecipeField( col, row[ col.key ] )
				) }
			</td>
		</tr>
	);
}

// Roles follow the column type: an image first column, then the name.
// With badges (Preset 3) the next text column holds chips and the one
// after it a price chip; every remaining column is a labeled field.
function renderRecipes( { columns, rows, hasBadges } ) {
	const { imageCol, titleCol, restCols } = getColumnRoles( columns );

	// An image cannot be a chip, so image columns stay labeled fields.
	const chipCols = hasBadges
		? restCols.filter( ( col ) => 'image' !== col.type )
		: [];
	const statCol = chipCols[ 0 ];
	const priceCol = chipCols[ 1 ];
	const roles = {
		imageCol,
		titleCol,
		statCol,
		priceCol,
		fieldCols: restCols.filter(
			( col ) => col !== statCol && col !== priceCol
		),
	};

	return (
		<table className="lunar-table__recipes">
			<tbody>
				{ rows.map( ( row, index ) =>
					row.isDivider
						? renderDividerRow(
								row,
								index,
								'lunar-table__recipes-divider-cell'
							)
						: renderRecipeCard( row, index, roles )
				) }
			</tbody>
		</table>
	);
}

export default function save( { attributes } ) {
	const {
		preset,
		columns,
		rows,
		enableSort,
		enableFilter,
		showCardNote,
		showCardHighlight,
	} = attributes;

	if ( ! columns.length ) {
		return null;
	}

	const isCards = isCardPreset( preset );
	const isRecipes = isRecipePreset( preset );

	const blockProps = useBlockProps.save( {
		className: 'lunar-table',
		'data-preset': preset,
		'data-sort': isTablePreset( preset ) && enableSort ? 'true' : 'false',
		'data-filter': enableFilter ? 'true' : 'false',
		// The stylesheet needs the column count to keep a Default table wide
		// enough to scroll instead of squeezing its columns, and the row count
		// of a card to line up the rows of Preset 2.
		style: {
			'--lunar-table-columns': columns.length,
			...( isCards && {
				'--lunar-table-card-rows': getCardRowCount(
					getCardRoles( columns, {
						showCardNote,
						showCardHighlight,
					} )
				),
			} ),
		},
	} );

	let tableMarkup;

	if ( isCards ) {
		tableMarkup = renderCards( {
			columns,
			rows,
			showCardNote,
			showCardHighlight,
		} );
	} else if ( isRecipes ) {
		tableMarkup = renderRecipes( {
			columns,
			rows,
			hasBadges: PRESET_3 === preset,
		} );
	} else {
		tableMarkup = renderTable( { columns, rows, preset } );
	}

	return <div { ...blockProps }>{ tableMarkup }</div>;
}
